function stringCount(n) {
  const MOD = 1000000007n;
  const len = BigInt(n);

  function power(base, exponent) {
    let result = 1n;
    while (exponent > 0n) {
      if (exponent % 2n === 1n) {
        result = result * base % MOD;
      }
      base = base * base % MOD;
      exponent /= 2n;
    }
    return result;
  }

  const all = power(26n, len);
  const singles = 3n * power(25n, len) + len * power(25n, len - 1n);
  const pairs = 3n * power(24n, len) + 2n * len * power(24n, len - 1n);
  const triples = power(23n, len) + len * power(23n, len - 1n);
  const good = all - singles + pairs - triples;
  return Number((good % MOD + MOD) % MOD);
}

