function stringCount(n) {
  // Build strings letter by letter, tracking only: seen an 'l'?, seen a 't'?, and how many 'e's (capped at 2).
  // Each step appends 'l', 't', 'e', or one of the 23 other letters.
  const MOD = 1000000007;
  const empty = () => [0, 1].map(() => [0, 1].map(() => [0, 0, 0]));
  let ways = empty();
  ways[0][0][0] = 1;
  for (let step = 0; step < n; step++) {
    const next = empty();
    const add = (l, t, e, count) => { next[l][t][e] = (next[l][t][e] + count) % MOD; };
    for (let l = 0; l < 2; l++)
      for (let t = 0; t < 2; t++)
        for (let e = 0; e < 3; e++) {
          const count = ways[l][t][e];
          if (!count) continue;
          add(1, t, e, count);
          add(l, 1, e, count);
          add(l, t, Math.min(2, e + 1), count);
          add(l, t, e, count * 23 % MOD);
        }
    ways = next;
  }
  return ways[1][1][2];
}

